                      onChange={(e) => onUpdateItem(selectedItem.id, { worldSimPrompt: e.target.value })}
                      className="w-full bg-black/40 border border-white/5 rounded-xl p-3 text-[11px] h-20 outline-none focus:border-indigo-500/30 transition-all placeholder:text-zinc-700"
                      placeholder="描述交互因果 (例如：盖子缓缓打开并冒出热气)..."
                   />
                   <div className="grid grid-cols-2 gap-2">
