import React, { useRef, useEffect } from 'react';
import { Point } from '../types';

interface AntigravityLoadingProps {
  width: number;
  height: number;
  mousePos: Point; 
  type?: 'image' | 'video';
}

interface Node {
  x: number;
  y: number;
  ox: number;
  oy: number;
  vx: number;
  vy: number;
}

const AntigravityLoading: React.FC<AntigravityLoadingProps> = ({ width, height, mousePos, type = 'image' }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const nodesRef = useRef<Node[]>([]);
  const frameRef = useRef<number>(0);

  useEffect(() => {
    const cols = 14;
    const rows = 14;
    const nodes: Node[] = [];
    for (let i = 0; i <= cols; i++) {
      for (let j = 0; j <= rows; j++) {
        const x = (i / cols) * width;
        const y = (j / rows) * height;
        nodes.push({ x, y, ox: x, oy: y, vx: 0, vy: 0 });
      }
    }
    nodesRef.current = nodes;
  }, [width, height]);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const render = (time: number) => {
      ctx.clearRect(0, 0, width, height);

      const nodes = nodesRef.current;
      const spring = 0.08;
      const friction = 0.82;
      const mouseRadius = 120;
      const mouseStrength = type === 'video' ? 0.8 : 0.5;

      nodes.forEach(node => {
        const dxO = node.ox - node.x;
        const dyO = node.oy - node.y;
        node.vx += dxO * spring;
        node.vy += dyO * spring;

        const dxM = node.x - mousePos.x;
        const dyM = node.y - mousePos.y;
        const dist = Math.sqrt(dxM * dxM + dyM * dyM);

        if (dist < mouseRadius) {
          const force = (mouseRadius - dist) / mouseRadius;
          node.vx += (dxM / dist) * force * mouseStrength * 60;
          node.vy += (dyM / dist) * force * mouseStrength * 60;
        }

        // Add "Motion Flow" if video
        if (type === 'video') {
            node.vx += Math.sin(time * 0.002 + node.oy * 0.05) * 0.5;
            node.vy += Math.cos(time * 0.002 + node.ox * 0.05) * 0.5;
        }

        node.vx *= friction;
        node.vy *= friction;
        node.x += node.vx;
        node.y += node.vy;
      });

      ctx.beginPath();
      ctx.strokeStyle = type === 'video' ? 'rgba(249, 115, 22, 0.15)' : 'rgba(99, 102, 241, 0.08)';
      ctx.lineWidth = 1;
      const cols = 14, rows = 14;
      for (let i = 0; i <= cols; i++) {
        for (let j = 0; j <= rows; j++) {
          const idx = i * (rows + 1) + j;
          if (i < cols) {
            const nextIdx = (i + 1) * (rows + 1) + j;
            ctx.moveTo(nodes[idx].x, nodes[idx].y);
            ctx.lineTo(nodes[nextIdx].x, nodes[nextIdx].y);
          }
          if (j < rows) {
            const nextIdx = i * (rows + 1) + (j + 1);
            ctx.moveTo(nodes[idx].x, nodes[idx].y);
            ctx.lineTo(nodes[nextIdx].x, nodes[nextIdx].y);
          }
        }
      }
      ctx.stroke();

      ctx.fillStyle = type === 'video' ? 'rgba(249, 115, 22, 0.4)' : 'rgba(99, 102, 241, 0.3)';
      nodes.forEach((node, i) => {
        if (i % 4 === 0) {
           ctx.beginPath(); ctx.arc(node.x, node.y, 1.2, 0, Math.PI * 2); ctx.fill();
        }
      });

      frameRef.current = requestAnimationFrame(render);
    };

    render(0);
    return () => cancelAnimationFrame(frameRef.current);
  }, [width, height, mousePos, type]);

  return (
    <div className="absolute inset-0 bg-white flex flex-col items-center justify-center pointer-events-none">
      <canvas ref={canvasRef} width={width} height={height} className="absolute inset-0" />

      <div className="relative z-10 flex flex-col items-center gap-6">
        <div className="relative w-20 h-20 animate-pulse">
           <svg viewBox="0 0 24 24" fill="none" className={`w-full h-full ${type === 'video' ? 'text-orange-500' : 'text-indigo-600'}`}>
             <path d="M12 0L14.5 9.5L24 12L14.5 14.5L12 24L9.5 14.5L0 12L9.5 9.5L12 0Z" fill="currentColor" className="drop-shadow-[0_0_15px_rgba(0,0,0,0.2)]" />
           </svg>
        </div>

        <div className="w-48 h-1 bg-zinc-100 rounded-full overflow-hidden relative border border-zinc-200/50 shadow-inner">
            <div className={`absolute top-0 bottom-0 ${type === 'video' ? 'bg-orange-500' : 'bg-indigo-600'} w-1/3 rounded-full animate-[loading-sweep_1.8s_infinite_ease-in-out]`} />
        </div>

        <div className="flex flex-col items-center gap-1">
            <span className={`text-[11px] font-black ${type === 'video' ? 'text-orange-600' : 'text-indigo-600'} uppercase tracking-[0.4em] animate-pulse`}>
              {type === 'video' ? 'Simulating Causality' : 'Syncretizing'}
            </span>
            <span className="text-[8px] font-bold text-zinc-400 uppercase tracking-widest opacity-60">
              {type === 'video' ? 'Gemini Veo 3.1 Motion Synthesis' : 'Gemini 3 Pro Vision'}
            </span>
        </div>
      </div>

      <style>{`
        @keyframes loading-sweep {
            0% { left: -40%; width: 20%; }
            50% { width: 60%; }
            100% { left: 110%; width: 10%; }
        }
      `}</style>
    </div>
  );
};

