                    if (tool === 'select' || tool === 'text') { e.stopPropagation(); const ns = e.shiftKey ? [...selection, item.id] : (selection.includes(item.id) ? selection : [item.id]); setSelection(ns); startTransform('drag', mouseCanvasPos, ns); } 
