        } else {
            finalPrompt = `${prompt}. ${getSpatialInstructions(spatial)} ${recipeInstruction || ''}. Style: ${styleSuffix}. 1k resolution.`;
        }

        parts.push({ text: finalPrompt });

        const config: any = { 
            imageConfig: { aspectRatio: normalizeAspectRatio(ratio) }, 
