import { useRef, useEffect, useState, useMemo, memo } from 'react';
import React from 'react';
import * as THREE from 'three';
import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls';
import { OBJLoader } from 'three/examples/jsm/loaders/OBJLoader';
import { SpatialConfig, PartCMF } from '../types';
import { CameraIcon, LayoutGridIcon } from './Icons';

interface ModelViewportProps {
  url: string;
  viewAngle?: 'front' | 'top' | 'side' | 'perspective';
  cameraMode?: 'perspective' | 'orthographic';
  explodeFactor?: number;
  knollingFactor?: number;
  activePartId?: string;
  highlightedPartIds?: string[];
  hiddenPartIds?: string[];
  colorSeed?: number;
  partColorMap?: Record<string, string>;
  partCMFMap?: Record<string, PartCMF>;
  wireframeMode?: boolean;
  showExplodeTrails?: boolean;
  onPartSelect?: (partId: string) => void;
  onPartHUD?: (partId: string, screenPos: { x: number, y: number }) => void;
  onProjectedPoints?: (points: { id: string, name: string, x: number, y: number, z: number }[]) => void;
  onCameraChange?: (spatial: SpatialConfig) => void;
  onLoadParts?: (parts: string[]) => void;
  width: number;
  height: number;
  spatialConfig?: SpatialConfig;
}

const lerpAngle = (start: number, end: number, alpha: number) => {
  return start + (Math.atan2(Math.sin(end - start), Math.cos(end - start)) * alpha);
};

const ModelViewport: React.FC<ModelViewportProps> = memo(({ 
  url, viewAngle = 'perspective', cameraMode = 'perspective', explodeFactor = 0, knollingFactor = 0, activePartId, highlightedPartIds = [], hiddenPartIds = [], colorSeed = 0, 
  partColorMap = {}, partCMFMap = {}, wireframeMode = false, showExplodeTrails = false,
  onPartSelect, onPartHUD, onProjectedPoints, onCameraChange, onLoadParts, width, height, spatialConfig
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const rendererRef = useRef<THREE.WebGLRenderer | null>(null);
  const sceneRef = useRef<THREE.Scene | null>(null);

  const perspectiveCameraRef = useRef<THREE.PerspectiveCamera | null>(null);
  const orthoCameraRef = useRef<THREE.OrthographicCamera | null>(null);
  const activeCameraRef = useRef<THREE.Camera | null>(null);

  const groupRef = useRef<THREE.Group | null>(null);
  const controlsRef = useRef<OrbitControls | null>(null);
  const modelBoxRef = useRef<THREE.Box3>(new THREE.Box3());

  const initialPositions = useRef<Map<string, THREE.Vector3>>(new Map());
  const relativeExplodeVectors = useRef<Map<string, THREE.Vector3>>(new Map());
  const partMaterials = useRef<Map<string, THREE.MeshStandardMaterial>>(new Map());

  const [cubeRotation, setCubeRotation] = useState({ x: 0, y: 0 });
  const isInterpolatingRef = useRef(false);
  const targetSpatialRef = useRef<SpatialConfig | null>(null);

  const raycaster = useMemo(() => new THREE.Raycaster(), []);

  const smoothNavigateTo = (azimuth: number, elevation: number) => {
    if (!controlsRef.current || !activeCameraRef.current) return;
    const currentDist = controlsRef.current.getDistance();
    targetSpatialRef.current = { azimuth, elevation, distance: currentDist, fov: 45 };
    isInterpolatingRef.current = true;
  };

  const syncCameras = (source: THREE.Camera, target: THREE.Camera) => {
    if (!modelBoxRef.current) return;
    target.position.copy(source.position);
    target.quaternion.copy(source.quaternion);

    if (target instanceof THREE.OrthographicCamera) {
        const size = modelBoxRef.current.getSize(new THREE.Vector3());
        const maxDim = Math.max(size.x, size.y, size.z);
        const aspect = width / height;
        const dist = source.position.length();
        const frustumSize = dist * 0.8; // Calibrate based on zoom
        target.left = -frustumSize * aspect;
        target.right = frustumSize * aspect;
        target.top = frustumSize;
        target.bottom = -frustumSize;
        target.updateProjectionMatrix();
    }
  };

  const handleToggleOrtho = () => {
      const nextMode = cameraMode === 'perspective' ? 'orthographic' : 'perspective';
      onCameraChange?.({ 
          ...spatialConfig || { azimuth: 45, elevation: 35, distance: 12, fov: 45 },
          fov: nextMode === 'orthographic' ? 1 : 45 
      });
  };

  useEffect(() => {
    if (!containerRef.current) return;

    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0xf4f4f5);
    sceneRef.current = scene;

    const aspect = width / height;
    const pCamera = new THREE.PerspectiveCamera(45, aspect, 0.1, 5000);
    perspectiveCameraRef.current = pCamera;

    const oCamera = new THREE.OrthographicCamera(-10 * aspect, 10 * aspect, 10, -10, 0.1, 5000);
    orthoCameraRef.current = oCamera;

    const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true, preserveDrawingBuffer: true });
    renderer.setSize(width, height);
    renderer.setPixelRatio(window.devicePixelRatio);
    containerRef.current.appendChild(renderer.domElement);
    rendererRef.current = renderer;

    const ambientLight = new THREE.AmbientLight(0xffffff, 0.8);
    scene.add(ambientLight);
    const keyLight = new THREE.DirectionalLight(0xffffff, 1.2);
    keyLight.position.set(10, 20, 15);
    scene.add(keyLight);

    const loader = new OBJLoader();
    loader.load(url, (obj) => {
      const group = obj;
      groupRef.current = group;
      scene.add(group);

      const box = new THREE.Box3().setFromObject(group);
      modelBoxRef.current = box;
      const center = box.getCenter(new THREE.Vector3());
      group.position.sub(center);

      const parts: string[] = [];
      group.traverse((child) => {
        if ((child as any).isMesh) {
          const mesh = child as THREE.Mesh;
          const meshBox = new THREE.Box3().setFromObject(mesh);
          const meshCenter = meshBox.getCenter(new THREE.Vector3());
          const pid = mesh.name || mesh.uuid;
          parts.push(pid);

          const material = new THREE.MeshStandardMaterial({ metalness: 0.3, roughness: 0.4, color: new THREE.Color(0xcccccc) });
          mesh.material = material;
          partMaterials.current.set(pid, material);
          initialPositions.current.set(mesh.uuid, mesh.position.clone());

          let explodeVec = meshCenter.clone().sub(new THREE.Vector3(0,0,0));
          if (explodeVec.length() < 0.1) explodeVec.set(0, 1, 0);
          explodeVec.normalize();
          relativeExplodeVectors.current.set(mesh.uuid, explodeVec);
        }
      });
      onLoadParts?.(parts);

      const maxDim = Math.max(box.getSize(new THREE.Vector3()).x, box.getSize(new THREE.Vector3()).y, box.getSize(new THREE.Vector3()).z);
      const viewDistance = maxDim * 2.5;

      const activeCam = cameraMode === 'orthographic' ? oCamera : pCamera;
      activeCameraRef.current = activeCam;
      activeCam.position.set(viewDistance * 0.7, viewDistance * 0.7, viewDistance * 0.7);
      activeCam.lookAt(0, 0, 0);

      const controls = new OrbitControls(activeCam, renderer.domElement);
      controls.enableDamping = true;
      controls.target.set(0, 0, 0);
      controls.addEventListener('change', () => {
          if (!activeCameraRef.current || !onCameraChange || isInterpolatingRef.current) return;
          const cam = activeCameraRef.current;
          const spherical = new THREE.Spherical().setFromVector3(cam.position);
          const azimuth = ((spherical.theta * 180 / Math.PI) % 360 + 360) % 360;
          const elevation = 90 - (spherical.phi * 180 / Math.PI);
          setCubeRotation({ x: elevation, y: -azimuth });
          onCameraChange({ azimuth, elevation, distance: spherical.radius, fov: (cam as any).fov || 45 });
      });
      controlsRef.current = controls;
    });

    let frameId: number;
    const animate = (time: number) => {
      frameId = requestAnimationFrame(animate);
      if (isInterpolatingRef.current && targetSpatialRef.current && activeCameraRef.current && controlsRef.current) {
          const cam = activeCameraRef.current;
          const currentSpherical = new THREE.Spherical().setFromVector3(cam.position);
          const targetPhi = (90 - targetSpatialRef.current.elevation) * (Math.PI / 180);
          const targetTheta = (targetSpatialRef.current.azimuth) * (Math.PI / 180);
          currentSpherical.phi = THREE.MathUtils.lerp(currentSpherical.phi, targetPhi, 0.1);
          currentSpherical.theta = lerpAngle(currentSpherical.theta, targetTheta, 0.1);
          cam.position.setFromSphericalCoords(currentSpherical.radius, currentSpherical.phi, currentSpherical.theta);
          cam.lookAt(0, 0, 0);
          if (Math.abs(currentSpherical.phi - targetPhi) < 0.001 && Math.abs(currentSpherical.theta - targetTheta) < 0.001) {
              isInterpolatingRef.current = false;
          }
      }
      if (controlsRef.current) controlsRef.current.update();
      if (rendererRef.current && sceneRef.current && activeCameraRef.current) {
        rendererRef.current.render(sceneRef.current, activeCameraRef.current);
      }
    };
    animate(0);

    return () => {
      cancelAnimationFrame(frameId);
      renderer.dispose();
      if (renderer.domElement && containerRef.current?.contains(renderer.domElement)) containerRef.current.removeChild(renderer.domElement);
    };
  }, [url, width, height]);

  // Handle mode toggle sync
  useEffect(() => {
    if (!activeCameraRef.current || !perspectiveCameraRef.current || !orthoCameraRef.current || !controlsRef.current) return;
    const isOrtho = cameraMode === 'orthographic';
    const nextCam = isOrtho ? orthoCameraRef.current : perspectiveCameraRef.current;
    if (activeCameraRef.current !== nextCam) {
        syncCameras(activeCameraRef.current, nextCam);
        activeCameraRef.current = nextCam;
        controlsRef.current.object = nextCam;
        controlsRef.current.update();
    }
  }, [cameraMode]);

  useEffect(() => {
    if (!groupRef.current) return;
    const maxDim = modelBoxRef.current.getSize(new THREE.Vector3()).length();
    groupRef.current.traverse((child) => {
      if ((child as any).isMesh) {
        const mesh = child as THREE.Mesh;
        const initial = initialPositions.current.get(mesh.uuid);
        const relVec = relativeExplodeVectors.current.get(mesh.uuid);
        if (initial && relVec) {
          const explodeOffset = relVec.clone().multiplyScalar(explodeFactor * maxDim * 0.5); 
          mesh.position.copy(initial.clone().add(explodeOffset));
        }
        mesh.visible = !hiddenPartIds?.includes(mesh.name || mesh.uuid);
      }
    });
  }, [explodeFactor, hiddenPartIds]);

  return (
    <div ref={containerRef} className="w-full h-full relative" style={{ touchAction: 'none' }}>
        <div className="absolute top-4 right-4 z-[100] flex flex-col items-center gap-6 pointer-events-auto select-none">
            {/* 3D ViewCube Skeleton UI */}
            <div className="relative w-24 h-24 perspective-1000">
                <div 
                    className="w-full h-full relative preserve-3d transition-transform duration-100 pointer-events-none"
                    style={{ transform: `rotateX(${cubeRotation.x}deg) rotateY(${cubeRotation.y}deg)` }}
                >
                    {/* Dashed Cube Frame */}
                    <div className="absolute inset-0 border-2 border-dashed border-zinc-500/20 translate-z-[40px]" />
                    <div className="absolute inset-0 border-2 border-dashed border-zinc-500/20 -translate-z-[40px]" />

                    {/* Face Diamonds */}
                    {[
                        { id: 'front', pos: 'translateZ(40px)', azi: 0, ele: 0 },
                        { id: 'back', pos: 'rotateY(180deg) translateZ(40px)', azi: 180, ele: 0 },
                        { id: 'top', pos: 'rotateX(90deg) translateZ(40px)', azi: 0, ele: 89 },
                        { id: 'bot', pos: 'rotateX(-90deg) translateZ(40px)', azi: 0, ele: -89 },
                        { id: 'left', pos: 'rotateY(-90deg) translateZ(40px)', azi: 270, ele: 0 },
                        { id: 'right', pos: 'rotateY(90deg) translateZ(40px)', azi: 90, ele: 0 },
                    ].map(f => (
                        <div 
                            key={f.id}
                            onClick={() => smoothNavigateTo(f.azi, f.ele)}
                            className={`absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-8 h-8 rotate-45 border border-zinc-500/40 pointer-events-auto cursor-pointer transition-all hover:bg-indigo-500/80 hover:border-indigo-400 ${f.id === 'top' ? 'bg-indigo-600/40' : 'bg-zinc-800/40'}`}
                            style={{ transform: `${f.pos} rotate(45deg)` }}
                        />
                    ))}

                    {/* Corner Nodes */}
                    {[
                        { id: 'c1', pos: 'translate3d(40px, 40px, 40px)', azi: 45, ele: 35 },
                        { id: 'c2', pos: 'translate3d(-40px, 40px, 40px)', azi: 315, ele: 35 },
                        { id: 'c3', pos: 'translate3d(40px, -40px, 40px)', azi: 135, ele: -35 },
                        { id: 'c4', pos: 'translate3d(-40px, -40px, 40px)', azi: 225, ele: -35 },
                        { id: 'c5', pos: 'translate3d(40px, 40px, -40px)', azi: 135, ele: 35 },
                        { id: 'c6', pos: 'translate3d(-40px, 40px, -40px)', azi: 225, ele: 35 },
                        { id: 'c7', pos: 'translate3d(40px, -40px, -40px)', azi: 45, ele: -35 },
                        { id: 'c8', pos: 'translate3d(-40px, -40px, -40px)', azi: 315, ele: -35 },
                    ].map(c => (
                        <div 
                            key={c.id}
                            onClick={() => smoothNavigateTo(c.azi, c.ele)}
                            className="absolute w-2.5 h-2.5 bg-zinc-600 rounded-full border border-white/20 pointer-events-auto cursor-pointer hover:bg-indigo-400 hover:scale-150 transition-all"
                            style={{ transform: c.pos }}
                        />
                    ))}
                </div>
            </div>

            {/* Viewport Toggles */}
            <div className="flex bg-[#18181b]/90 backdrop-blur-xl border border-white/5 rounded-full p-1.5 shadow-2xl gap-1">
                <button 
                    onClick={handleToggleOrtho} 
                    className={`w-9 h-9 rounded-full flex items-center justify-center transition-all ${cameraMode === 'perspective' ? 'bg-indigo-600 text-white shadow-lg' : 'text-zinc-500 hover:text-zinc-300'}`}
                    title="Perspective (P)"
                >
                    <CameraIcon className="w-4 h-4" />
                </button>
                <button 
                    onClick={handleToggleOrtho} 
                    className={`w-9 h-9 rounded-full flex items-center justify-center transition-all ${cameraMode === 'orthographic' ? 'bg-indigo-600 text-white shadow-lg' : 'text-zinc-500 hover:text-zinc-300'}`}
                    title="Orthographic (O)"
                >
                    <LayoutGridIcon className="w-4 h-4" />
                </button>
            </div>
        </div>
        <style>{`
            .perspective-1000 { perspective: 1000px; }
            .preserve-3d { transform-style: preserve-3d; }
            .translate-z-40 { transform: translateZ(40px); }
        `}</style>
    </div>
  );
}, (prev, next) => prev.url === next.url && prev.viewAngle === next.viewAngle && prev.cameraMode === next.cameraMode && prev.explodeFactor === next.explodeFactor && prev.knollingFactor === next.knollingFactor && prev.activePartId === next.activePartId && prev.width === next.width && JSON.stringify(prev.hiddenPartIds) === JSON.stringify(next.hiddenPartIds) && JSON.stringify(prev.spatialConfig) === JSON.stringify(next.spatialConfig));

export default ModelViewport;

import { useState, useEffect, useMemo, useRef } from 'react';
import React from 'react';
import { CanvasItem, ItemType, EditToolType, GenerationSettings, SpatialConfig, IdentifiedPoint, PartCMF } from '../types';
import { 
  SparklesIcon, RefreshIcon, EraserIcon, 
  ScissorsIcon, VectorIcon, 
  UpscaleIcon, SlidersIcon, ChevronRightIcon,
  ChevronLeftIcon, SquareIcon, TrashIcon,
  FileIcon, CopyIcon, EvolutionIcon,
  LassoIcon, BrushIcon, TypeIcon, CreativeScaleIcon, ZapIcon,
  PaletteIcon, XIcon, FocusIcon,
  MessageCircleIcon, TargetIcon, WandIcon, LinkIcon, CameraIcon,
  MaximizeIcon, BoxIcon, CheckIcon, RotateCcwIcon, MagicCurveIcon,
  MergeIcon, FrameIcon, ExpandIcon, LayoutGridIcon, GripIcon, ShuffleIcon,
  GalleryIcon, TerminalIcon, PlusIcon,
  ArrowIcon, FlaskIcon, EyeIcon, SearchIcon, EyeOffIcon, ListOrderedIcon, UndoIcon,
  VideoIcon, PlayIcon, ChevronDownIcon
} from './Icons';
import SpatialController from './SpatialController';
import { getEvolutionStage } from '../services/evolutionService';
import { CMF_LIBRARY } from '../constants';
import { generateInteractionSuggestions, generateAdaptiveCausalCommands } from '../services/geminiService';

type PanelView = 'main' | 'variations' | 'edit_area' | 'adjust_colors' | 'change_bg' | 'evolution' | 'spatial' | 'transplant' | 'model_3d' | 'world_sim';

interface PropertiesPanelProps {
  selectedItem: CanvasItem | null;
  selectedItems?: CanvasItem[];
  onUpdateItem: (id: string, updates: Partial<CanvasItem>) => void;
  onGenerate: (id: string, overridePrompt?: string, settings?: Partial<GenerationSettings>) => void;
  onDelete: (id: string) => void;
  onAutoPrompt?: (id: string) => Promise<void>;
  onEnterEditMode?: (tool: EditToolType) => void;
  onExitEditMode?: () => void;
  initialView?: {view: string, ts: number} | null;
  onSendToPrompt?: (id: string) => void;
  onSendToGemini?: (id: string) => void;
  onSyncPointsToGemini?: (id: string) => void;
  onFrameAction?: (id: string, action: 'merge' | 'expand' | 'crop') => void;
  editTool?: EditToolType;
  setEditTool?: (tool: EditToolType) => void;
  brushSize?: number;
  setBrushSize?: (size: number) => void;
  onApplyEdit?: (prompt: string) => void;
  onClearMask?: () => void;
  onJSONAnalysis?: (id: string) => void;
  isAnalyzingJSON?: boolean;
  onStartPickPoint?: (id: string, temperature: number) => void;
  isPickingPoint?: boolean;
  currentEvolutionLevel?: number;
  isCncMode: boolean;
  setIsCncMode: (val: boolean) => void;
  onUpdatePoint?: (itemId: string, pointId: string, updates: Partial<IdentifiedPoint>) => void;
  onClearAllPoints?: (itemId: string) => void;
  onCommitPointChanges?: (itemId: string) => void;
  onAutoAlign?: (sourceId: string, targetId: string) => Promise<void>;
  onClosePanel?: () => void;
  onFloatingAction?: (id: string, action: string) => void;
}

const PropertiesPanel: React.FC<PropertiesPanelProps> = ({ 
  selectedItem, selectedItems = [], onUpdateItem, onGenerate, onDelete, onAutoPrompt, 
  onEnterEditMode, onExitEditMode, initialView, onSendToPrompt, onSendToGemini, onSyncPointsToGemini,
  onFrameAction, editTool = 'brush', setEditTool, brushSize = 30, setBrushSize, onApplyEdit, onClearMask,
  onJSONAnalysis, isAnalyzingJSON, onStartPickPoint, isPickingPoint, currentEvolutionLevel = 60,
  isCncMode, setIsCncMode, onUpdatePoint, onClearAllPoints, onCommitPointChanges, onAutoAlign, onClosePanel,
  onFloatingAction
}) => {
  const [currentView, setCurrentView] = useState<PanelView>('main');
  const [localPrompt, setLocalPrompt] = useState('');
  const [modelCommand, setModelCommand] = useState('');
  const [isCommandFocused, setIsCommandFocused] = useState(false);
  const [activeTab, setActiveTab] = useState<'actions' | 'details' | 'nodes'>('actions');
  const [artisticLevel, setArtisticLevel] = useState(currentEvolutionLevel);
  const [usePro, setUsePro] = useState(true);

  const [dynamicSuggestions, setDynamicSuggestions] = useState<string[]>([]);
  const [adaptiveCausal, setAdaptiveCausal] = useState<{ cat: string, tags: string[] }[]>([]);
  const [isRefreshingSuggestions, setIsRefreshingSuggestions] = useState(false);
  const [isCausalCollapsed, setIsCausalCollapsed] = useState(true); // Default collapsed

  const handleRefreshCausal = async () => {
    if (!selectedItem || selectedItem.type !== ItemType.MODEL || isRefreshingSuggestions) return;
    setIsRefreshingSuggestions(true);
    try {
        const modelName = selectedItem.content || "Industrial Product";
        const [suggestions, causal] = await Promise.all([
            generateInteractionSuggestions(modelName),
            generateAdaptiveCausalCommands(modelName)
        ]);
        setDynamicSuggestions(suggestions);
        setAdaptiveCausal(causal);
        setIsCausalCollapsed(false);
    } catch (e) { console.error("Adaptive fetch failed", e); }
    finally { setIsRefreshingSuggestions(false); }
  };

  useEffect(() => {
    if (selectedItem?.type === ItemType.MODEL && adaptiveCausal.length === 0) {
        handleRefreshCausal();
    }
  }, [selectedItem?.id]);

  if (!selectedItem) return null;

  const handleExecuteModelCommand = (cmdText?: string) => {
    const finalCmd = cmdText || modelCommand;
    if (!finalCmd.trim()) return;
    onFloatingAction?.(selectedItem.id, `model_cmd:${finalCmd}`);
    setModelCommand('');
    setIsCommandFocused(false);
  };

  const handleAppendCausalTag = (tag: string) => {
    const currentPrompt = selectedItem.worldSimPrompt || '';
    const newPrompt = currentPrompt ? `${currentPrompt}\n${tag}` : tag;
    onUpdateItem(selectedItem.id, { worldSimPrompt: newPrompt });
  };

  return (
    <div className="w-full h-full bg-[#09090b] border border-zinc-800 rounded-[24px] shadow-3xl overflow-hidden flex flex-col pointer-events-auto backdrop-blur-md">
